export const parties=[['Union','CDU / CSU','#434750'],['SPD','Social Democrats','#e64348'],['Greens','Bündnis 90 / Die Grünen','#23965c'],['FDP','Free Democrats','#cfad00'],['AfD','Alternative für Deutschland','#159ed3'],['The Left','Die Linke','#c63c83'],['BSW','Bündnis Sahra Wagenknecht','#883b75']];
// Positions are editorial interpretations of the 2025 federal programmes.
// 1: supports, -1: opposes, 0: qualified/mixed, null: insufficient evidence.
export const questions=[
['Taxes','Economy & public services','Very large fortunes should be taxed more heavily.','Additional revenue can fund public services and reduce the concentration of wealth.','Wealth taxes can discourage investment, encourage capital to move abroad and be difficult to administer.',[-1,1,1,-1,-1,1,1]],
['Public investment','Economy & public services','Germany should allow more borrowing for long-term public investment.','Future generations benefit from functioning infrastructure; postponing repairs also creates costs.','More borrowing brings interest costs and can weaken incentives to prioritise spending.',[0,1,1,-1,-1,1,1]],
['Industrial policy','Economy & public services','The state should actively fund the transformation of strategic industries.','Public investment can protect essential capacity and support innovations with long-term benefits.','Politicians can back the wrong businesses; competition and broad tax relief may use resources better.',[-1,1,1,-1,-1,1,1]],
['Welfare sanctions','Work & everyday life','Benefits should be cut more sharply when someone refuses suitable work without good reason.','Conditions encourage participation and help maintain fairness to workers who finance the system.','Cuts can deepen poverty and make finding stable work harder; support may address the actual barriers.',[1,0,-0.5,1,1,-1,0]],
['Minimum wage','Work & everyday life','Politicians should mandate a higher minimum wage instead of leaving increases solely to the wage commission.','A stronger wage floor protects low-paid workers and supports household purchasing power.','Politically set increases may ignore business conditions and put some jobs or working hours at risk.',[-1,1,1,-1,-1,1,1]],
['Pension funding','Work & everyday life','A greater share of retirement provision should come from invested funds.','Investment returns diversify pension funding as fewer workers support more retirees.','Returns fluctuate, management has costs, and moving contributions can leave a gap in current pension funding.',[1,0,0,1,0,-1,-1]],
['Rent protection','Work & everyday life','Germany should introduce stronger limits on rent increases.','Limits protect tenants from displacement while new housing takes years to arrive.','Strict limits can discourage maintenance and new rental supply and favour existing tenants over newcomers.',[0,1,1,-1,-1,1,1]],
['Health insurance','Economy & public services','Everyone should contribute to a common statutory health-insurance system.','A broader risk pool can distribute costs more fairly and reduce differences in access to care.','Keeping statutory and private insurance preserves choice and avoids a disruptive system transition.',[-1,1,1,-1,-1,1,1]],
['Climate ambition','Climate & mobility','Germany should keep a binding climate-neutrality target of 2045 or earlier.','A firm deadline supports predictable investment and limits future climate damage.','A later or more flexible target gives households and industry longer to adapt and can lower transition costs.',[1,1,1,-1,-1,1,-1]],
['Nuclear energy','Climate & mobility','Germany should pursue a return to nuclear electricity generation.','Nuclear power can provide dependable low-carbon electricity and diversify energy supply.','New plants are costly and slow to build; waste and decommissioning remain long-term responsibilities.',[1,-1,-1,1,1,-1,null]],
['Transport','Climate & mobility','The EU should retain its 2035 zero-emission standard for new cars.','A clear timetable accelerates cleaner vehicles and gives manufacturers a predictable direction.','A technology-specific transition may limit consumer choice and burden buyers without affordable alternatives.',[-1,0,1,-1,-1,1,-1]],
['Asylum','Migration & rights','Germany should generally refuse asylum processing for people arriving through safe third countries.','Supporters argue that responsibility should rest elsewhere and that limits ease pressure on local services.','Blanket refusal can undermine individual protection; workable responsibility-sharing needs European cooperation.',[1,-1,-1,0.5,1,-1,1]],
['Citizenship','Migration & rights','Well-integrated residents should generally be able to naturalise after five years and keep another nationality.','Citizenship supports participation and belonging without requiring people to cut ties to their origin.','Opponents prefer longer evidence of integration and question whether dual nationality creates competing obligations.',[-1,1,1,1,-1,1,-1]],
['Digital privacy','Migration & rights','Authorities should be allowed to retain everyone’s communications metadata without individual suspicion.','Stored records may help investigators trace serious crimes when a suspect is identified later.','Indiscriminate retention affects innocent people and creates risks of misuse and breaches.',[1,0,-1,-1,-1,-1,0]],
['Ukraine','Europe & security','Germany should continue supplying weapons to Ukraine.','Military aid supports self-defence and may strengthen Ukraine’s negotiating position and European security.','Opponents worry about escalation, prolonged fighting and the diversion of resources from other priorities.',[1,1,1,1,-1,-1,-1]],
['Defence','Europe & security','Germany should substantially increase resources for its armed forces.','Credible defence can deter attack and reduce reliance on allies for protection.','Higher military spending competes with public services and may contribute to an arms race.',[1,1,1,1,1,-1,-1]],
['European cooperation','Europe & security','EU foreign-policy decisions should more often use majority votes instead of national vetoes.','Majority voting can make Europe faster and stronger when one government blocks collective action.','A national veto protects countries from being bound to major policies their voters oppose.',[1,1,1,1,-1,0,-1]],
['Legal self-determination','Migration & rights','Adults should be able to change their legal gender through a declaration without a medical assessment.','A simpler process respects personal autonomy and avoids medical gatekeeping of legal identity.','Opponents argue that independent checks protect the integrity of legal records and sex-based safeguards.',[-1,1,1,1,-1,1,-1]]
].map(([topic,category,statement,pro,con,positions],i)=>({id:i+1,topic,category,statement,pro,con,positions}));
export const sources=[['CDU / CSU','https://www.cdu.de/wahlprogramm-von-cdu-und-csu/'],['SPD','https://www.spd.de/bundestagswahl/programm'],['Greens','https://www.gruene.de/artikel/zusammen-wachsen'],['FDP','https://www.fdp.de/bundestagswahl-2025-alles-laesst-sich-aendern'],['AfD','https://www.afd.de/afd_bundestagswahlprogramm2025_web/'],['The Left','https://www.die-linke.de/bundestagswahl-2025/wahlprogramm/'],['BSW','https://hb.bsw-vg.de/das-bsw-wahlprogramm-zur-bundestagswahl-202/']];
export function rank(answers){return parties.map((p,j)=>{let total=0,count=0;questions.forEach((q,i)=>{if(answers[i]===null||answers[i]===undefined||answers[i]===0||q.positions[j]===null)return;total+=1-Math.abs(answers[i]-q.positions[j])/2;count++});return {party:j,score:count?Math.round(total/count*100):null,count}}).sort((a,b)=>(b.score??-1)-(a.score??-1)||a.party-b.party)};
